options.css:
@ #RFQStatus {
	display: list-item;
	list-style-type: disc;
	list-style-position: inside;
}@ 

#RFQStatus span {
	position: relative;
	left: -10px
}@

.vendor-score {
	border-radius: 4px;
	line-height: 18px;
	font-size: 11px;
	font-family: "Roboto Bold", sans-serif;
	color: #fff;
	width: 18px;
	min-width: 18px;
	height: 18px;
	display: flex;
	align-items: center;
	justify-content: center;
	margin: 6px 0;
	cursor: help;
	float: right;
}

.vendor-score.no-score {
	font-size: 8px;
}

.vendor-score.max-score {
	font-size: 9px
}

@ .comparison-table-container {
	--comparator-border-color: #d7d9db;

	margin-right: 15px;
	margin-top: 25px;

	.comparison-table {
		width: 100%;
		border-collapse: collapse;
		contain: paint;
		table-layout: fixed;
		min-width: calc(300px + 180px * attr(data-nb-vendors type(<integer>)));

		thead {
			th {
				padding: 20px 10px;
				background-color: white;

				&.item-column {
					max-width: 280px;
					width: 280px;
				}

				&.vendor-column {
					border-top: 1px solid var(--comparator-border-color);
					border-right: 1px solid var(--comparator-border-color);
					border-left: 1px solid var(--comparator-border-color);
					div.vendor-header-detailed {
						display: flex;
						flex-direction: column;
						gap: 4px;
						justify-content: center;
						align-items: center;
						width: fit-content;
						max-width: 100%;
						margin: auto;

						div {
							display: flex;
							gap: 3px;
							align-items: center;
							max-width: 100%;
							color: var(--text-color-color5);

							&.vendor-main-info {
								font-size: 20px;
								line-height: 25px;
								font-family: "Roboto Bold", sans-serif;

								.vendor-score {
									float: none;
								}

								.vendor-name {
									overflow: hidden;
									text-overflow: ellipsis;
									max-width: 100%;
								}
							}

							i.material-symbols-rounded {
								font-size: 15px;
							}

							span {
								font-weight: normal;
							}
						}
					}
				}
			}
		}

		tbody {
			border-right: 1px solid var(--comparator-border-color);
			border-left: 1px solid var(--comparator-border-color);
			border-bottom: 1px solid var(--comparator-border-color);

			tr.section-title-row {
				background-color: var(--table-header-cell-background-color, var(--otherlist-header-background-color));
				color: var(--element-text-secondary-color, white);
				border-right: 1px solid var(--comparator-border-color);
				border-left: 1px solid var(--comparator-border-color);
				td.section-title {
					padding: 2px 0px;
					span.section-title-content {
						text-transform: uppercase;
						padding-left: 5px;
					}
				}
			}

			tr.questionnaire-header-row ~ tr.questionnaire-header-row,
			tr.item-header-row ~ tr.item-header-row {
				border-top: 3px solid var(--comparator-border-color);
			}

			tr.questionnaire-header-row,
			tr.item-header-row {
				td {
					&.section-label-header,
					&.item-name-header {
						padding-left: 15px;
						padding-top: 5px;
						padding-bottom: 5px;

						.item-main-name {
							color: var(--text-color-color5);
							font-size: 14px;
							line-height: 21px;
							overflow: hidden;
							text-overflow: ellipsis;
							font-family: "Roboto Bold", sans-serif;
							display: block;
							display: -webkit-box;
							-webkit-line-clamp: 2;
							-webkit-box-orient: vertical;
							white-space: normal;
						}
					}
				}

				.tag-container {
					min-height: 24px;
					text-align: center;
				}
			}

			tr.questionnaire-row,
			tr.item-info-row {
				&.even-row {
					background-color: var(--main-color-grey-less-light);
				}

				td {
					padding: 5px 10px;

					.item-main-name {
						min-height: 24px;
					}

					&.question-title,
					&.line-title,
					&.info-label {
						color: var(--text-color-color1);
						font-family: "Roboto Bold", sans-serif;
						text-align: right;
						padding-right: 10px;
						overflow: hidden;
						text-overflow: ellipsis;
						display: block;
						display: -webkit-box;
						-webkit-line-clamp: 4;
						-webkit-box-orient: vertical;
						white-space: normal;
						line-height: 20px;
					}

					&.vendor-cell {
						text-align: center;
						color: var(--text-color-color5);

						.best-value {
							font-family: "Roboto Bold", sans-serif;
						}

						.question-answer,
						.item-comment {
							overflow: hidden;
							text-overflow: ellipsis;
							display: block;
							display: -webkit-box;
							-webkit-line-clamp: 4;
							-webkit-box-orient: vertical;
							white-space: pre-wrap;
							text-align: center;
						}
					}
				}
			}

			tr.documents-info-row {
				&:nth-child(even) {
					background-color: var(--main-color-grey-less-light);
				}

				td {
					border-right: 1px solid var(--comparator-border-color);
					border-left: 1px solid var(--comparator-border-color);
					padding: 5px 10px;

					&.info-label {
						color: var(--text-color-color1);
						font-family: "Roboto Bold", sans-serif;
						text-align: right;
						padding-right: 10px;
					}

					&.vendor-cell {
						text-align: center;

						a {
							text-decoration: underline;
							color: var(--text-color-color5);
							text-overflow: ellipsis;
							overflow: hidden;
							display: block;
						}
					}
				}
			}

			tr {
				td.vendor-cell,
				td.vendor-header-cell {
					border-right: 1px solid var(--comparator-border-color);
					border-left: 1px solid var(--comparator-border-color);
				}
			}
		}
	}
}
